tool_input.command:
$h=@{'User-Agent'='dsh-agent'}
Write-Output '=== catalog/dsh-plugin.json ==='
try { (Invoke-WebRequest 'https://raw.githubusercontent.com/Fish-under-sea/dsh-our-free-model-fish/main/catalog/dsh-plugin.json' -Headers $h -TimeoutSec 25 -UseBasicParsing).Content } catch { Write-Output "FAILED: $($_.Exception.Message)" }
Write-Output ''
Write-Output '=== files mentioning pricing / area in src ==='
try { (Invoke-RestMethod 'https://api.github.com/repos/Fish-under-sea/dsh-our-free-model-fish/git/trees/main?recursive=1' -Headers $h -TimeoutSec 30).tree | Where-Object { $_.path -match '(?i)pricing|area|visibility|channel' } | Select-Object -ExpandProperty path } catch { Write-Output "FAILED: $($_.Exception.Message)" }
